import * as THREE from 'three';
import {clone} from '../lab/vendor/SkeletonUtils.js';
const variants=[
 {name:'Nova',shirt:0x617256,skin:0xffffff,hair:0x503b2c,eye:0x576f3d,background:0x15271f},
 {name:'Atlas',shirt:0x56463f,skin:0xe3c4aa,hair:0x26211f,eye:0x657684,background:0x20202b,short:true,glasses:true},
 {name:'Sol',shirt:0x764d39,skin:0xa87954,hair:0x241914,eye:0x73553b,background:0x2b211a,curls:true},
 {name:'Creator',shirt:0x314b4a,skin:0xffeee0,hair:0x443128,eye:0x547b6b,background:0x182a28},
 {name:'ECHO',shirt:0xaaa995,skin:0xe6d9d0,hair:0xbac3c3,eye:0x728d9a,background:0x1e2829,short:true,glasses:false}
];
function attachAt(bone,obj,position,model){obj.position.set(...position);model.add(obj);model.updateMatrixWorld(true);if(bone)bone.attach(obj)}
export function makeCharacter(base,index){const v=variants[index],model=clone(base),scene=new THREE.Scene(),bones={},morphs=[];scene.background=new THREE.Color(v.background);scene.add(model);
 model.traverse(o=>{if(o.isBone)bones[o.name]={bone:o,rest:o.quaternion.clone()};if(o.isMesh){o.frustumCulled=false;if(o.morphTargetDictionary)morphs.push(o);if(o.name.includes('high-poly'))o.visible=false;if((v.short||v.curls)&&o.name.includes('ponytail'))o.visible=false;const materials=(Array.isArray(o.material)?o.material:[o.material]).map(original=>{const m=original.clone();if(m.name.includes('casual')){m.map=null;m.color.set(v.shirt);m.roughness=.85;m.metalness=0}if(m.name.includes('body')){m.color.set(v.skin);m.roughness=.78}if(m.name.includes('ponytail')){m.color.set(v.hair);m.roughness=.85}if(m.name.includes('eyelashes')){m.color.set(0x211713);m.transparent=true;m.opacity=.65;m.depthWrite=false}if(m.name.includes('eyebrows'))m.color.set(v.hair);return m});o.material=Array.isArray(o.material)?materials:materials[0]}});
 model.updateMatrixWorld(true);
 for(const [side,x]of [['LeftEye',.0325],['RightEye',-.0325]]){const g=new THREE.Group();g.add(new THREE.Mesh(new THREE.SphereGeometry(.0168,24,16),new THREE.MeshPhysicalMaterial({color:0xf2ebe2,roughness:.18,clearcoat:1})));const iris=new THREE.Mesh(new THREE.CircleGeometry(.0068,32),new THREE.ShaderMaterial({uniforms:{irisColor:{value:new THREE.Color(v.eye)}},vertexShader:'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:'uniform vec3 irisColor;varying vec2 vUv;void main(){vec2 p=(vUv-.5)*2.0;float r=length(p);float a=atan(p.y,p.x);float fibers=sin(a*45.0+r*30.0)*.5+.5;vec3 c=mix(irisColor*.38,irisColor,fibers);c*=1.0-smoothstep(.78,1.0,r)*.8;c=mix(c,vec3(.008,.015,.012),1.0-smoothstep(.34,.4,r));gl_FragColor=vec4(c,1.0);}'}));iris.position.z=.0163;g.add(iris);const pupil=new THREE.Mesh(new THREE.CircleGeometry(.0028,24),new THREE.MeshBasicMaterial({color:0x07110c}));pupil.position.z=.0165;g.add(pupil);const glint=new THREE.Mesh(new THREE.SphereGeometry(.0014,8,6),new THREE.MeshBasicMaterial({color:0xffffff}));glint.position.set(-.002,.0024,.0169);g.add(glint);attachAt(bones[side]?.bone,g,[x,1.6515,.129],model)}
 const hairMaterial=new THREE.MeshStandardMaterial({color:v.hair,roughness:.9});
 if(v.short){const cap=new THREE.Mesh(new THREE.SphereGeometry(1,32,18,0,Math.PI*2,0,Math.PI*.47),hairMaterial);cap.scale.set(.096,.10,.089);attachAt(bones.Head?.bone,cap,[0,1.691,.013],model);for(const x of [-.083,.083]){const side=new THREE.Mesh(new THREE.SphereGeometry(1,12,12),hairMaterial);side.scale.set(.015,.052,.061);attachAt(bones.Head?.bone,side,[x,1.699,-.006],model)}}
 if(v.curls){const hair=new THREE.Group();const geo=new THREE.SphereGeometry(.024,10,8);for(let row=0;row<6;row++){const phi=.12+row*.23;for(let j=0;j<15;j++){const a=j/15*Math.PI*2+row*.3;const curl=new THREE.Mesh(geo,hairMaterial);curl.position.set(Math.sin(phi)*Math.cos(a)*.103,Math.cos(phi)*.115,Math.sin(phi)*Math.sin(a)*.098);curl.scale.setScalar(.88+.15*Math.sin(j*8+row));hair.add(curl)}}attachAt(bones.Head?.bone,hair,[0,1.68,.003],model)}
 if(v.glasses){const glasses=new THREE.Group(),material=new THREE.MeshStandardMaterial({color:0xb8aa95,metalness:.7,roughness:.3});for(const x of [-.033,.033]){const rim=new THREE.Mesh(new THREE.TorusGeometry(.023,.0015,6,32),material);rim.scale.y=.8;rim.position.x=x;glasses.add(rim)}const bridge=new THREE.Mesh(new THREE.CylinderGeometry(.0014,.0014,.019,6),material);bridge.rotation.z=Math.PI/2;glasses.add(bridge);attachAt(bones.Head?.bone,glasses,[0,1.653,.151],model)}
 const morphBindings=morphs.flatMap(mesh=>Object.entries(mesh.morphTargetDictionary).map(([name,index])=>({mesh,name,index})));
 return {scene,model,bones,morphs,morphBindings,index,blinkAt:2+index*.43,blinkStart:-1,entered:performance.now(),shirt:v.shirt};
}
